RebornTalentGuideWDData={version="TG2A",layoutHash="8c3e9decc0d8dc5c7c0092578b9975ca91d133d00f215bd659408962eaa59ebc",nodes={[29744]={["id"]=29744,["name"]="治疗守卫",["en"]="Healing Ward",["max"]=1,["tab"]="Class",["pool"]="AE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\a67e84177d7d6ae4",["effects"]={"学会治疗守卫：每2.5秒治疗30码内最多8名自己或队伍/团队友方，优先受伤目标。治疗量随等级成长，获得18.5%治疗加成和8%远程攻击强度加成。"},["limit"]="与其他基础守卫共用一个名额；召唤物到期或被替换后停止治疗。",["level"]=10,["path"]="起始节点，无技能前置。"},[6054]={["id"]=6054,["name"]="灵性传统",["en"]="Spiritual Traditions",["max"]=1,["tab"]="Class",["pool"]="AE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\4b9ae58172b94ea3",["effects"]={"受到伤害时的施法打退幅度降低70%；施法耗蓝后仍保留40%的自然精神回蓝。"},["limit"]="不免疫打断或沉默；不是每次施法返还40%法力。固定每5秒回蓝仍按原规则处理。",["level"]=12,["path"]="治疗守卫，或拟态守卫。"},[6047]={["id"]=6047,["name"]="睿智",["en"]="Wizened",["max"]=2,["tab"]="Class",["pool"]="AE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\b6123da942e5d1ee",["effects"]={"最大法力提高5%，标准法术与技能消耗降低3%。","最大法力提高10%，标准法术与技能消耗降低6%。这是总收益，不与1级再次叠加。"},["limit"]="提高法力上限不会立即回满法力；自定义扣费或清空资源的技能沿用其自身规则。",["level"]=10,["path"]="灵性传统；当前版本按此路线接入。"},[7092]={["id"]=7092,["name"]="寻觅者",["en"]="Seeker",["max"]=1,["tab"]="Class",["pool"]="AE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\73a906b399b2326f",["effects"]={"本人的守卫、神像及雕像召唤法术，标准法力消耗降低20%。"},["limit"]="一键放置分别计算每个召唤法术；回收按实际支付的法力返还，不额外返还节省的部分。",["level"]=10,["path"]="灵性传统。"},[29309]={["id"]=29309,["name"]="净化神像",["en"]="Cleansing Idol",["max"]=1,["tab"]="Class",["pool"]="AE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\3222f93950cf3124",["effects"]={"学会净化神像，持续60秒。放置3秒后首次净化，此后每3秒为30码内视线可达的自己和队伍成员，各驱散1个疾病和1个中毒效果。"},["limit"]="与其他神像共用一个名额；不驱散诅咒或魔法效果。",["level"]=16,["path"]="睿智至少1级，或寻觅者至少1级。"},[29301]={["id"]=29301,["name"]="拟态守卫",["en"]="Mimic Ward",["max"]=1,["tab"]="Class",["pool"]="AE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\3bef5b03373191ee",["effects"]={"学会拟态守卫：持续12秒，复制你的恶意之怒和洛阿佳酿，60秒冷却。"},["limit"]="独立于普通守卫；未点天选之人时保留一个拟态守卫，复制目标需在守卫40码内且视线可达。",["level"]=10,["path"]="通用树起始节点。"},[4004]={["id"]=4004,["name"]="傀儡师之线",["en"]="Puppeteer's Threads",["max"]=1,["tab"]="Voodoo",["pool"]="FREE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\555ac266fe3c4f3b",["effects"]={"直接伤害技能留下10秒丝线，储存你造成伤害的15%，结束时一次结算。"},["limit"]="周期伤害不能独自建立丝线，已有丝线时可储存；爆发不再次储存。",["level"]=10,["path"]="本方案绑定巫毒；0 AE / 0 TE。"},[31154]={["id"]=31154,["name"]="暗影傀儡",["en"]="Shadow Puppets",["max"]=1,["tab"]="Voodoo",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\2eeb5c4aa8b1cdfb",["effects"]={"解锁暗影傀儡：每0.75秒造成一次暗影伤害，持续3秒；每跳额外获得22%暗影法强加成并收集灵魂。18秒冷却，技能等级随角色升级。"},["limit"]="1点TE解锁整条技能等级链；不是每个技能等级重复消耗TE。",["level"]=11,["path"]="同时需要傀儡师之线和拟态守卫。"},[31344]={["id"]=31344,["name"]="荆棘谷风格",["en"]="Stranglethorn Style",["max"]=1,["tab"]="Voodoo",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\1e9d98eaf72e9f5e",["effects"]={"暴击几率提高4个百分点；巫毒攻击法术威胁降低20%。"},["limit"]="仅当前激活且已保存的方案生效；1 TE解锁，后续技能等级免费。",["level"]=10,["path"]="本方案绑定巫毒，无其他技能前置。"},[31340]={["id"]=31340,["name"]="扎拉赞恩的恶意",["en"]="Zalazane's Malice",["max"]=1,["tab"]="Voodoo",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\50cf42358cca0d23",["effects"]={"恶意妖术周期伤害提高15%；诅咒持续时间增加2秒，仍遵守PVP上限和递减。"},["limit"]="仅当前激活且已保存的方案生效；1 TE解锁，后续技能等级免费。",["level"]=10,["path"]="本方案绑定巫毒，无其他技能前置。"},[7157]={["id"]=7157,["name"]="妖火",["en"]="Hexfire",["max"]=1,["tab"]="Voodoo",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\e3662f6f3ee1c310",["effects"]={"造成火焰伤害；火焰法强高于自然法强时加55%火焰法强，否则加55%自然法强及50%精神。"},["limit"]="仅当前激活且已保存的方案生效；1 TE解锁，后续技能等级免费。",["level"]=15,["path"]="本方案绑定巫毒，无其他技能前置。"},[6058]={["id"]=6058,["name"]="黑暗魔法",["en"]="Dark Magic",["max"]=1,["tab"]="Voodoo",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\5a891f84c0b5d178",["effects"]={"恶意之怒和邪恶巫毒的施法时间减少0.5秒。"},["limit"]="只匹配这两类技能；不影响其他施法，也不直接提高伤害。",["level"]=10,["path"]="巫毒方案，无额外技能前置；1 TE。"},[29928]={["id"]=29928,["name"]="邪恶巫毒",["en"]="Bad Juju",["max"]=1,["tab"]="Voodoo",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\ec10d335ff8a93f5",["effects"]={"向目标施放暗影伤害；对已被恶意妖术影响的目标命中后，附加治疗效果降低。"},["limit"]="1 TE解锁；22/28/34/40/46/52/58/60级自动补技能等级，不额外收费。沿用已有伤害和减疗实现。",["level"]=15,["path"]="巫毒方案，无额外技能前置。图中的连接线不等于强制前置。"},[30973]={["id"]=30973,["name"]="女巫会之杖",["en"]="Staff of the Coven",["max"]=3,["tab"]="Voodoo",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\3f4ca8e6152dce83",["effects"]={"精神提高8%，近战、远程与法术命中率提高2%。","精神提高16%，近战、远程与法术命中率提高4%。","精神提高25%，近战、远程与法术命中率提高6%。"},["limit"]="每级1 TE，共3级；只保留最高级，不叠加三个等级。",["level"]=10,["path"]="巫毒方案，无额外前置。"},[4533]={["id"]=4533,["name"]="巫毒之力",["en"]="Voodoo Power",["max"]=1,["tab"]="Voodoo",["pool"]="FREE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\142b65e460e8eb1d",["effects"]={"获得相当于精神50%的法术伤害，以及精神5%的法术命中等级。"},["limit"]="20级，0 AE／0 TE；随当前已保存方案生效。命中等级不是命中率。",["level"]=20,["path"]="巫毒方案，无额外前置。"},[31341]={["id"]=31341,["name"]="这就是巫毒",["en"]="It's Da Voodoo",["max"]=1,["tab"]="Voodoo",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\52f1d0480757fbb8",["effects"]={"暗影烈焰伤害提高25%。"},["limit"]="与空灵之魂二选一；只提高暗影烈焰伤害，不影响妖火。",["level"]=10,["path"]="先在巫毒投入8 TE，再花1 TE学习；AE不能代替。"},[6045]={["id"]=6045,["name"]="空灵之魂",["en"]="Hollow Spirit",["max"]=1,["tab"]="Voodoo",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\0ea0a29b65b82261",["effects"]={"暗影烈焰或妖火造成有效伤害后，使存活敌人被法术和武器攻击暴击的几率提高3个百分点，持续12秒。"},["limit"]="与这就是巫毒二选一；刷新持续时间，不叠层。触发它的本次伤害不追溯提高暴击率。",["level"]=10,["path"]="先投入8点巫毒TE，再花1 TE；不能同时选择这就是巫毒。"},[31347]={["id"]=31347,["name"]="妖术迸发",["en"]="Hexplosion",["max"]=1,["tab"]="Voodoo",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\6195d8ff9eab3ce5",["effects"]={"本人攻击造成有效伤害并暴击时，获得20%施法急速，持续6秒；再次触发刷新，不叠层。"},["limit"]="只增加施法急速，不增加近战或远程攻击速度；不由治疗、召唤物或完全吸收触发。",["level"]=10,["path"]="先投入8点基础巫毒TE，再花1 TE。"},[31348]={["id"]=31348,["name"]="恶意滋长",["en"]="Growing Malice",["max"]=1,["tab"]="Voodoo",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\f5a4a25286af2547",["effects"]={"自己的恶意妖术造成有效周期伤害后叠1层；下一跳每层伤害提高3%，最多10层即30%。"},["limit"]="不同目标和施法者独立计层；原妖术移除或此被动取消时清理本人层数，不改动原始周期快照。",["level"]=10,["path"]="先投入8点基础巫毒TE，再花1 TE；战斗中需要自己的恶意妖术。"},[6644]={["id"]=6644,["name"]="恶性蔓延",["en"]="Malignant",["max"]=1,["tab"]="Voodoo",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\a32ba9a42840760f",["effects"]={"邪恶巫毒或妖火造成有效伤害后，将受击者身上属于你的恶意妖术蔓延到8码内另一个合法敌人，最多1个。"},["limit"]="继承剩余时间、下一跳时间、伤害和暴击快照；不复制他人妖术，不重复初始伤害，不覆盖目标已有的自身妖术。",["level"]=10,["path"]="先投入8点基础巫毒TE，再花1 TE；需要受击者身上有自己的恶意妖术。"},[6046]={["id"]=6046,["name"]="金度之怒",["en"]="Jin'do's Wrath",["max"]=1,["tab"]="Voodoo",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\a431c6433fd71142",["effects"]={"妖火暴击率提高25个百分点；暴击额外伤害提高25%。"},["limit"]="只影响妖火各技能等级；沿用原生暴击差额倍率，不把150%直接变成187.5%。",["level"]=10,["path"]="先投入8点基础巫毒TE，再花1 TE。"},[6062]={["id"]=6062,["name"]="仪式妖术",["en"]="Ritual Hexing",["max"]=2,["tab"]="Voodoo",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\3e41423e10180a62",["effects"]={"对带有你自己的恶意妖术的敌人，恶意之怒、邪恶巫毒和妖火伤害提高10%。","上述三类技能伤害提高20%；这是总收益，不与1级叠加。"},["limit"]="不由别人施加的妖术启用；不增加妖术周期伤害、暗影烈焰或召唤物伤害。",["level"]=10,["path"]="先投入8点基础巫毒TE，每级另花1 TE，共2级。"},[30889]={["id"]=30889,["name"]="延续恶意",["en"]="Prolonged Malice",["max"]=1,["tab"]="Voodoo",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\cbd8dc711f5a43a1",["effects"]={"新施放的恶意妖术基础持续时间增加6秒；已适配的攻击巫毒技能射程增加6码。"},["limit"]="只延长恶意妖术；射程匹配恶意之怒、恶意妖术、邪恶巫毒、妖火、暗影傀儡及四种已移植诅咒。不扩大AOE、蔓延、雕像或守卫半径。",["level"]=10,["path"]="先投入8点基础巫毒TE，再花1 TE；旧妖术和洗点后的剩余时间不倒算。"},[31343]={["id"]=31343,["name"]="充盈巫毒",["en"]="Overflowing Juju",["max"]=1,["tab"]="Voodoo",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\f30225a2b7d9