项1 TE。",["level"]=20,["path"]="需要相连前置与此前暗影TE。"},[7355]={["id"]=7355,["name"]="狂乱灵魂",["en"]="Frenzied Spirits",["max"]=1,["tab"]="Shadowhunting",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\2b126870dc830b88",["effects"]={"消耗当前全部灵魂，每层提供10点远程暴击等级、5%暴击伤害增幅，以及实际伤害2%的自我治疗；每层使效果持续4秒。期间每秒获得1层灵魂，最多5层；至少需要1层灵魂。20秒冷却，14%基础法力。"},["limit"]="仅当前已保存激活方案；每项1 TE。",["level"]=20,["path"]="需要相连前置与此前暗影TE。"},[7102]={["id"]=7102,["name"]="暗影追猎",["en"]="Shadowstalker",["max"]=1,["tab"]="Shadowhunting",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\08f5d713d1253654",["effects"]={"进入强化潜行并清除有害效果，移动速度提高50%，持续20秒。攻击会解除潜行；180秒冷却。"},["limit"]="仅当前已保存激活方案；每项1 TE。",["level"]=27,["path"]="需要相连前置及8点此前暗影TE；本批节点不计入此前点数。"},[5303]={["id"]=5303,["name"]="巫毒饥渴",["en"]="Voodoo Hunger",["max"]=1,["tab"]="Shadowhunting",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\5a01d84d7ee83c93",["effects"]={"在自己的暗影追猎或幻象效果期间，每0.5秒获得1层巫毒饥渴，最多10层。每层使下一次主动恶毒箭伤害提高10%；叠层持续8秒，成功施放后消耗。"},["limit"]="仅当前已保存激活方案；每项1 TE。",["level"]=27,["path"]="需要相连前置及8点此前暗影TE；本批节点不计入此前点数。"},[4177]={["id"]=4177,["name"]="死亡妖术",["en"]="Hex of Death",["max"]=1,["tab"]="Shadowhunting",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\ee106dea3f01c60b",["effects"]={"恶毒箭造成实际伤害时施加死亡妖术，使目标受到的治疗每层降低20%，最多2层（40%），持续10秒。与灵魂狩猎二选一；目标显示真实减疗图标和层数。"},["limit"]="仅当前已保存激活方案；每项1 TE。",["level"]=27,["path"]="需要相连前置及8点此前暗影TE；本批节点不计入此前点数。"},[11177]={["id"]=11177,["name"]="灵魂狩猎",["en"]="Spirit Hunting",["max"]=1,["tab"]="Shadowhunting",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\0f7d82f8ba5a054d",["effects"]={"每次成功主动施放恶毒箭，以施法前灵魂层数判定：每层提供15%几率额外获得1层灵魂（0/15/30/45/60/75%），最多5层。不消耗灵魂；触发施法不重复获取。与死亡妖术二选一。"},["limit"]="仅当前已保存激活方案；每项1 TE。",["level"]=27,["path"]="需要相连前置及8点此前暗影TE；本批节点不计入此前点数。"},[7103]={["id"]=7103,["name"]="幽影战刃",["en"]="Umbral Glaive",["max"]=1,["tab"]="Shadowhunting",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\20a7673ea4296d97",["effects"]={"远程攻击实际命中造成伤害时，有10%＋远程暴击等级所提供的暴击百分比几率触发10秒幽影战刃，将最高等级恶意妖术按钮临时替换。消耗触发施放：对主目标及其10码内最多2敌人施加6秒吸血，每秒造成基础值＋10%远程攻击强度的暗影伤害并恢复自身生命；刷新自己的恶意妖术。9%基础法力，无公共冷却；原始恶意妖术宏仍可施放。"},["limit"]="仅当前已保存激活方案；每项1 TE。",["level"]=30,["path"]="需要对应等级与相连前置。灵魂震击另需8点此前暗影TE。"},[4423]={["id"]=4423,["name"]="森金学徒",["en"]="Sen'jin's Apprentice",["max"]=1,["tab"]="Shadowhunting",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\124a1fb361f7e0ca",["effects"]={"远程攻击强度提高，数值为智力的100%加敏捷的25%；法术伤害强度提高，数值为敏捷的25%。随当前属性动态更新，不提高治疗强度。"},["limit"]="仅当前已保存激活方案；每项1 TE。",["level"]=40,["path"]="需要对应等级与相连前置。灵魂震击另需8点此前暗影TE。"},[29977]={["id"]=29977,["name"]="灵魂震击",["en"]="Spirit Shock",["max"]=1,["tab"]="Shadowhunting",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\1959db4105c60580",["effects"]={"使敌人沉默4秒；对非玩家目标另外打断当前施法，并使被打断法术所属学派锁定4秒。28秒冷却，25%基础法力，无公共冷却；玩家仅沉默，免疫/递减遵循原生规则。"},["limit"]="仅当前已保存激活方案；每项1 TE。",["level"]=31,["path"]="需要对应等级与相连前置。灵魂震击另需8点此前暗影TE。"},[12145]={["id"]=12145,["name"]="灵魂齐射",["en"]="Spirit Volley",["max"]=1,["tab"]="Shadowhunting",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\12e7c6e620ed6b46",["effects"]={"施放普通恶毒箭或灵魂回收有30%几率触发6秒就绪，将最高等级灵魂回收按钮临时变为灵魂齐射。齐射造成范围暗影伤害，增加28.5%远程攻击强度；成功施放收集1层灵魂并将灵魂战刃当前剩余冷却缩短3秒。原灵魂回收宏仍可用；0 AE/TE。"},["limit"]="仅当前已保存激活方案。灵魂齐射免费，另两项各1 TE。",["level"]=50,["path"]="50级、森金学徒；灵魂齐射免费。"},[7781]={["id"]=7781,["name"]="邦桑迪的赠礼",["en"]="Bwonsamdi's Gift",["max"]=1,["tab"]="Shadowhunting",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\9bb9434434013591",["effects"]={"自己的拟态守卫存活时，远程急速提高15%，并将最高等级灵魂回收临时变为灵魂齐射。每层灵魂使齐射伤害提高2%，最多10%；额外拟态也计入，其他玩家的守卫不计入。"},["limit"]="仅当前已保存激活方案。灵魂齐射免费，另两项各1 TE。",["level"]=20,["path"]="23点此前暗影TE；驭蛇者、毒蛇守卫、巨蛇诡计任一相连前置。"},[6076]={["id"]=6076,["name"]="代价",["en"]="A Price To Pay",["max"]=1,["tab"]="Shadowhunting",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\759ba9b94a7556f3",["effects"]={"拥有5层灵魂时成功施放灵魂蚀，立即重置灵魂战刃剩余冷却，并获得8秒增益：下一次普通灵魂战刃必定暴击，该次战刃还使暗影追猎当前剩余冷却缩短15秒。只影响战刃，不消耗灵魂；未命中不保证造成伤害。"},["limit"]="仅当前已保存激活方案。灵魂齐射免费，另两项各1 TE。",["level"]=20,["path"]="23点此前暗影TE；驭蛇者、毒蛇守卫、愚者把戏任一相连前置。"},[5235]={["id"]=5235,["name"]="毒蛇守卫",["en"]="Viper Ward",["max"]=1,["tab"]="Shadowhunting",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\ad151417197bcace",["effects"]={"将瑟拉图斯的召唤转换为独立毒蛇守卫：指定位置召唤1只，持续20秒，基础每秒攻击一次。每次攻击有50%＋远程暴击等级提供的暴击百分点几率释放妖火冲击，造成216＋15%远程AP火焰伤害。45秒冷却，14%基础法力；与驭蛇者二选一。"},["limit"]="仅当前已保存激活方案；每项1 TE。",["level"]=20,["path"]="23点此前暗影TE及相连前置；正常点数最早57级。毒蛇与驭蛇者互斥。"},[6388]={["id"]=6388,["name"]="愚者把戏",["en"]="Fool's Play",["max"]=1,["tab"]="Shadowhunting",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\7e0e28e89bb24ea7",["effects"]={"复制敌人20秒，使用目标真实近战伤害、攻击间隔和当前/最大生命值攻击该目标，并把目标施放的可复制原生伤害法术反打回去。120秒冷却，17%基础法力，20码；目标死亡或不再敌对时清理。治疗、召唤、光环和带专用脚本的复杂法术不复制。"},["limit"]="仅当前已保存激活方案；每项1 TE。",["level"]=31,["path"]="23点此前暗影TE及相连前置；正常点数最早57级。毒蛇与驭蛇者互斥。"},[29978]={["id"]=29978,["name"]="狂暴",["en"]="Berserking",["max"]=1,["tab"]="Shadowhunting",["pool"]="TE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\52409095ba749f1b",["effects"]={"自己的周期伤害有25%几率使自己当前蛇类守卫获得3%攻击急速，持续15秒，最多3层（9%）；包括普通蛇、群蛇、妖火群蛇和毒蛇，不作用于治疗守卫或拟态。"},["limit"]="仅当前已保存激活方案。",["level"]=30,["path"]="需要8点此前暗影TE；每级1TE。"},[5113]={["id"]=5113,["name"]="诅咒雕像",["en"]="Cursed Effigy",["max"]=1,["tab"]="Class",["pool"]="AE",["icon"]="Interface\\AddOns\\RebornWitchDoctorTalents\\Icons\\ad6f5becce9a22c3",["effects"]={"在附近放置诅咒雕像，持续15秒，15码内可见且敌对的目标不能暴击；离开范围或雕像消失后清除。与其他雕像共享一个槽，60秒冷却。"},["limit"]="仅当前已保存激活方案。",["level"]=58,["path"]="58级，24点此前通用AE；本层不互相凑点，花费1AE。"}},plans={{["key"]="leveling",["title"]="练级 · 暗影续航",["spec"]=2,["purpose"]="单人任务与逐个清怪；先补伤害、回魂与自保，低等级不推荐尚未解锁的大招。",["order"]={4006,12086,4505,4506,{1969,2},{7779,2},8574,30895,7086,6072,6074,6063,6069,30892,{6983,2},11164,29729,{6011,2},6073,7031,29930,6010,29981,4572,7103,4423,12145,7102,5303,11177,2997